import time
from dataclasses import dataclass
from typing import Callable

@dataclass
class TokenBucket:
    capacity: float
    refill_per_sec: float
    clock: Callable[[], float]
    tokens: float = 0.0

    def __post_init__(self):
        self.tokens = self.capacity

    def allow(self, cost: float = 1) -> bool:
        elapsed_time = self.clock() - self._last_refill_time
        self._last_refill_time = self.clock()
        tokens_to_refill = self.refill_per_sec * elapsed_time
        self.tokens = min(self.capacity, self.tokens + tokens_to_refill)
        if self.tokens >= cost:
            self.tokens -= cost
            return True
        return False

    @property
    def tokens(self) -> float:
        elapsed_time = self.clock() - self._last_refill_time
        self._last_refill_time = self.clock()
        tokens_to_refill = self.refill_per_sec * elapsed_time
        self.tokens = min(self.capacity, self.tokens + tokens_to_refill)
        return self.tokens

    def _last_refill_time(self) -> float:
        return self.clock()

def clock() -> float:
    return time.time()
